#!/usr/bin/env python3
"""Render extrusion moves of the 'Embossed text' object (M486 S0) from a gcode file to a PNG."""
import re, zlib, struct, sys

SRC = "/app/text.gcode"
DST = "/tmp/text_render.png"
W, H = 2000, 2000
PAD = 5  # mm padding

segs = []
x = y = 0.0
obj = -1
abs_xy = True
abs_e = False  # M83 in header -> relative extrusion

with open(SRC) as f:
    for line in f:
        line = line.split(";", 1)[0].strip()
        if not line:
            continue
        m = re.match(r"M486\s+S(-?\d+)", line)
        if m:
            obj = int(m.group(1))
            continue
        parts = line.split()
        cmd = parts[0].upper()
        if cmd == "G90":
            abs_xy = True; abs_e = True; continue
        if cmd == "G91":
            abs_xy = False; abs_e = False; continue
        if cmd == "M83":
            abs_e = False; continue
        if cmd == "M82":
            abs_e = True; continue
        if cmd == "G92":
            continue  # E reset irrelevant for relative extrusion
        if cmd in ("G0", "G1"):
            nx, ny, e = x, y, 0.0
            has_e = False
            for p in parts[1:]:
                c = p[0].upper()
                try:
                    v = float(p[1:])
                except ValueError:
                    continue
                if c == "X":
                    nx = v if abs_xy else x + v
                elif c == "Y":
                    ny = v if abs_xy else y + v
                elif c == "E":
                    e = v
                    has_e = True
            if obj == 0 and has_e and e > 0 and (nx != x or ny != y):
                segs.append((x, y, nx, ny))
            x, y = nx, ny

if not segs:
    sys.exit("no extrusion segments found for object 0")

minx = min(min(a, c) for a, b, c, d in segs) - PAD
maxx = max(max(a, c) for a, b, c, d in segs) + PAD
miny = min(min(b, d) for a, b, c, d in segs) - PAD
maxy = max(max(b, d) for a, b, c, d in segs) + PAD

sx = (W - 1) / (maxx - minx)
sy = (H - 1) / (maxy - miny)
s = min(sx, sy)

def px(mx, my):
    ix = int((mx - minx) * s)
    iy = int((maxy - my) * s)  # flip Y: gcode Y+ is up
    return ix, iy

img = bytearray(W * H)  # 0 = black bg, 255 = white

def plot(ix, iy):
    if 0 <= ix < W and 0 <= iy < H:
        img[iy * W + ix] = 255

def draw(x1, y1, x2, y2):
    # thick line: draw Bresenham plus neighbors for thickness
    dx = abs(x2 - x1); dy = -abs(y2 - y1)
    stx = 1 if x1 < x2 else -1
    sty = 1 if y1 < y2 else -1
    err = dx + dy
    while True:
        for ox in (-1, 0, 1):
            for oy in (-1, 0, 1):
                plot(x1 + ox, y1 + oy)
        if x1 == x2 and y1 == y2:
            break
        e2 = 2 * err
        if e2 >= dy:
            err += dy; x1 += stx
        if e2 <= dx:
            err += dx; y1 += sty

for a, b, c, d in segs:
    x1, y1 = px(a, b)
    x2, y2 = px(c, d)
    draw(x1, y1, x2, y2)

# grayscale PNG
raw = b"".join(b"\x00" + bytes(img[r * W:(r + 1) * W]) for r in range(H))
def chunk(tag, data):
    return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xffffffff)
png = b"\x89PNG\r\n\x1a\n"
png += chunk(b"IHDR", struct.pack(">IIBBBBB", W, H, 8, 0, 0, 0, 0))
png += chunk(b"IDAT", zlib.compress(bytes(raw), 9))
png += chunk(b"IEND", b"")
with open(DST, "wb") as f:
    f.write(png)
print(f"segments={len(segs)} bbox=({minx:.1f},{miny:.1f})-({maxx:.1f},{maxy:.1f}) -> {DST}")

